-- ─────────────────────────────────────────────────────────────────────────────
-- AgileProjection · NT-AI Network — Project Library Seed (Neon Postgres)
-- ─────────────────────────────────────────────────────────────────────────────
-- Run this in your Neon SQL editor AFTER `bun run db:push:pg` to populate the
-- Project Library with 5 ready-made internship starter projects.
--
-- Each project ships its starter files INLINE as a JSON array — no separate
-- ZIP upload required. The student download endpoint
--   /api/student/project-library/<id>/download?file=<fileName>
-- serves whichever file the student requests, while enforcing the
-- "one ready-made project per student" rule.
--
-- Idempotent: deletes existing library items first, then re-inserts.
-- ─────────────────────────────────────────────────────────────────────────────

DELETE FROM "ProjectSubmission" WHERE "projectId" IN (
  SELECT id FROM "ProjectLibraryItem" WHERE slug IN (
    'ai-procurement-assistant',
    'ai-resume-screening',
    'enterprise-ai-chatbot',
    'smart-business-dashboard',
    'internship-pm-portal'
  )
);
DELETE FROM "ProjectDownload" WHERE "projectId" IN (
  SELECT id FROM "ProjectLibraryItem" WHERE slug IN (
    'ai-procurement-assistant',
    'ai-resume-screening',
    'enterprise-ai-chatbot',
    'smart-business-dashboard',
    'internship-pm-portal'
  )
);
DELETE FROM "ProjectLibraryItem"
WHERE slug IN (
  'ai-procurement-assistant',
  'ai-resume-screening',
  'enterprise-ai-chatbot',
  'smart-business-dashboard',
  'internship-pm-portal'
);

-- ─────────────────────────────────────────────────────────────────────────────
-- NOTE: starterFiles is a JSONB/text column holding a JSON array of
--   [{ "label": "README", "fileName": "README.md", "language": "markdown", "content": "..." }]
-- In the seed SQL we use PostgreSQL's dollar-quoted strings ($$...$$) so the
-- Python/code content (which contains single + double quotes) doesn't break.
-- ─────────────────────────────────────────────────────────────────────────────

INSERT INTO "ProjectLibraryItem"
  ("id", "slug", "title", "description", "techStack", "difficulty", "category",
   "features", "starterFiles", "status", "accessLevel", "featured",
   "createdBy", "createdAt", "updatedAt")
VALUES

-- 1. AI Procurement Assistant ───────────────────────────────────────────────
(
  'proj_ai_procurement',
  'ai-procurement-assistant',
  'AI Procurement Assistant',
  'Build a tool for supplier evaluation, purchase recommendations, and procurement analytics. The assistant ingests vendor catalogs + past PO history, scores suppliers on quality/price/lead-time, and recommends the best vendor for a new requisition.',
  'Python / FastAPI / PostgreSQL',
  'Intermediate',
  'AI',
  '["Supplier scoring (quality, price, lead-time)","Purchase recommendation engine","Procurement analytics dashboard","REST API with FastAPI","PostgreSQL persistence"]',
  $J$[{"label":"README","fileName":"README.md","language":"markdown","content":"# AI Procurement Assistant\n\nBuild a tool for supplier evaluation, purchase recommendations, and procurement analytics.\n\n## Stack\n- Python 3.11\n- FastAPI (REST API)\n- PostgreSQL + SQLAlchemy\n- scikit-learn (scoring model)\n\n## Setup\n```bash\npip install -r requirements.txt\npsql -f database/schema.sql\nuvicorn app.main:app --reload\n```\n\n## Endpoints\n- `POST /suppliers` — register a supplier\n- `POST /requisitions` — submit a purchase requisition\n- `GET /recommend?category=...` — top-3 suppliers ranked\n- `GET /analytics/lead-time` — avg lead-time by category\n\n## Project Structure\n```\napp/\n  main.py\n  models/\n  routers/\n  ml/\n    scorer.py\ndatabase/\n  schema.sql\ntests/\n```\n"},{"label":"requirements","fileName":"requirements.txt","language":"text","content":"fastapi==0.115.0\nuvicorn[standard]==0.32.0\nsqlalchemy==2.0.35\npsycopg2-binary==2.9.9\npydantic==2.9.2\nscikit-learn==1.5.2\npandas==2.2.3\nnumpy==1.26.4\npython-dotenv==1.0.1\n"},{"label":"FastAPI app","fileName":"app/main.py","language":"python","content":"from fastapi import FastAPI, Depends, HTTPException\nfrom pydantic import BaseModel\nfrom sqlalchemy.orm import Session\n\nfrom app.db import get_db, Supplier, Requisition\nfrom app.ml.scorer import score_suppliers\n\napp = FastAPI(title=\"AI Procurement Assistant\", version=\"0.1.0\")\n\nclass SupplierIn(BaseModel):\n    name: str\n    category: str\n    quality_score: float    # 0-1\n    avg_price: float        # INR\n    avg_lead_days: int\n\nclass RequisitionIn(BaseModel):\n    category: str\n    qty: int\n    budget: float\n\n@app.get(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\n@app.post(\"/suppliers\", status_code=201)\ndef add_supplier(s: SupplierIn, db: Session = Depends(get_db)):\n    obj = Supplier(**s.dict())\n    db.add(obj); db.commit(); db.refresh(obj)\n    return {\"id\": obj.id}\n\n@app.get(\"/recommend\")\ndef recommend(category: str, db: Session = Depends(get_db)):\n    rows = db.query(Supplier).filter(Supplier.category == category).all()\n    if not rows:\n        raise HTTPException(404, \"No suppliers in this category\")\n    ranked = score_suppliers(rows)\n    return {\"top\": ranked[:3]}\n\n@app.post(\"/requisitions\", status_code=201)\ndef create_req(r: RequisitionIn, db: Session = Depends(get_db)):\n    obj = Requisition(**r.dict())\n    db.add(obj); db.commit(); db.refresh(obj)\n    return {\"id\": obj.id}\n"},{"label":"ML scorer","fileName":"app/ml/scorer.py","language":"python","content":"import numpy as np\n\ndef score_suppliers(suppliers):\n    \"\"\"Rank suppliers by a weighted combination of quality (↑), price (↓), lead-time (↓).\"\"\"\n    out = []\n    for s in suppliers:\n        # Normalised scores in [0, 1]\n        quality = s.quality_score\n        price   = 1.0 - min(s.avg_price / 100000.0, 1.0)   # 100k INR = max\n        lead    = 1.0 - min(s.avg_lead_days / 30.0, 1.0)   # 30 days = max\n        score   = 0.5 * quality + 0.3 * price + 0.2 * lead\n        out.append({\n            \"id\": s.id, \"name\": s.name,\n            \"score\": round(float(score), 4),\n            \"breakdown\": {\n                \"quality\": round(float(quality), 3),\n                \"price\":   round(float(price), 3),\n                \"lead\":    round(float(lead), 3),\n            }\n        })\n    out.sort(key=lambda x: x[\"score\"], reverse=True)\n    return out\n"},{"label":"DB schema","fileName":"database/schema.sql","language":"sql","content":"CREATE TABLE IF NOT EXISTS suppliers (\n  id           SERIAL PRIMARY KEY,\n  name         TEXT NOT NULL,\n  category     TEXT NOT NULL,\n  quality_score REAL NOT NULL CHECK (quality_score BETWEEN 0 AND 1),\n  avg_price    REAL NOT NULL,\n  avg_lead_days INT NOT NULL,\n  created_at   TIMESTAMPTZ DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_suppliers_category ON suppliers(category);\n\nCREATE TABLE IF NOT EXISTS requisitions (\n  id        SERIAL PRIMARY KEY,\n  category  TEXT NOT NULL,\n  qty       INT  NOT NULL,\n  budget    REAL NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT NOW()\n);\n"}]$J$,
  'published', 'public', true,
  'admin', NOW(), NOW()
),

-- 2. AI Resume Screening System ─────────────────────────────────────────────
(
  'proj_ai_resume',
  'ai-resume-screening',
  'AI Resume Screening System',
  'Analyze resumes, extract skills using NLP, and compare candidates against job requirements. Outputs a shortlist ranked by match score with explainability.',
  'Python / NLP / React',
  'Intermediate',
  'AI',
  '["Resume PDF parsing","Skill extraction with spaCy NER","Job-description matching (TF-IDF + cosine)","React dashboard for HR","Explainable match scores"]',
  $J$[{"label":"README","fileName":"README.md","language":"markdown","content":"# AI Resume Screening System\n\nAnalyze resumes, extract skills using NLP, and rank candidates against a job description.\n\n## Stack\n- Backend: Python 3.11 + FastAPI\n- NLP: spaCy + scikit-learn\n- Frontend: React 18 + Vite + TailwindCSS\n\n## Run\n```bash\n# Backend\ncd backend && pip install -r requirements.txt\npython -m spacy download en_core_web_sm\nuvicorn app.main:app --reload --port 8000\n\n# Frontend\ncd frontend && npm install && npm run dev\n```\n\n## Project Structure\n```\nbackend/\n  app/\n    main.py\n    nlp/\n      skill_extractor.py\n    ml/\n      matcher.py\n  sample_resumes/\nfrontend/\n  src/\n    App.jsx\n    components/\n```\n"},{"label":"Backend deps","fileName":"backend/requirements.txt","language":"text","content":"fastapi==0.115.0\nuvicorn[standard]==0.32.0\nspacy==3.7.6\nscikit-learn==1.5.2\nPyPDF2==3.0.1\npython-multipart==0.0.12\npydantic==2.9.2\n"},{"label":"Skill extractor","fileName":"backend/app/nlp/skill_extractor.py","language":"python","content":"import spacy\nfrom collections import defaultdict\n\n_NLP = spacy.load(\"en_core_web_sm\")\n\n# A small built-in skill vocabulary — extend with a real KB in production\nSKILL_VOCAB = {\n  \"python\", \"java\", \"javascript\", \"react\", \"node\", \"fastapi\", \"django\",\n  \"sql\", \"postgres\", \"mongodb\", \"aws\", \"docker\", \"kubernetes\",\n  \"machine learning\", \"deep learning\", \"nlp\", \"pandas\", \"numpy\",\n  \"tensorflow\", \"pytorch\", \"scikit-learn\", \"tableau\", \"powerbi\"\n}\n\ndef extract_skills(text: str) -> list[str]:\n    doc = _NLP(text.lower())\n    found = set()\n    for chunk in doc.noun_chunks:\n        if chunk.text.strip() in SKILL_VOCAB:\n            found.add(chunk.text.strip())\n    # also token-level match (single-word skills)\n    for tok in doc:\n        if tok.text in SKILL_VOCAB and len(tok.text) > 1:\n            found.add(tok.text)\n    return sorted(found)\n"},{"label":"Matcher","fileName":"backend/app/ml/matcher.py","language":"python","content":"from sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.metrics.pairwise import cosine_similarity\n\ndef match_resumes(job_desc: str, resumes: list[dict]) -> list[dict]:\n    \"\"\"resumes: [{ id, name, text }]\n    Returns: [{ id, name, score }] sorted desc by score.\"\"\"\n    if not resumes:\n        return []\n    corpus = [job_desc] + [r[\"text\"] for r in resumes]\n    vec = TfidfVectorizer(stop_words=\"english\", ngram_range=(1, 2))\n    tfidf = vec.fit_transform(corpus)\n    sims = cosine_similarity(tfidf[0:1], tfidf[1:]).flatten()\n    ranked = sorted(\n        ({\"id\": r[\"id\"], \"name\": r[\"name\"], \"score\": float(s)} for r, s in zip(resumes, sims)),\n        key=lambda x: x[\"score\"], reverse=True\n    )\n    return ranked\n"},{"label":"FastAPI app","fileName":"backend/app/main.py","language":"python","content":"from fastapi import FastAPI, UploadFile, File, Form\nfrom PyPDF2 import PdfReader\nfrom app.nlp.skill_extractor import extract_skills\nfrom app.ml.matcher import match_resumes\n\napp = FastAPI(title=\"AI Resume Screening\", version=\"0.1.0\")\n\n@app.get(\"/health\")\ndef health(): return {\"status\": \"ok\"}\n\n@app.post(\"/screen\")\nasync def screen(job_desc: str = Form(...), files: list[UploadFile] = File(...)):\n    resumes = []\n    for f in files:\n        reader = PdfReader(f.file)\n        text = \" \".join(p.extract_text() or \"\" for p in reader.pages)\n        resumes.append({\"id\": f.filename, \"name\": f.filename, \"text\": text})\n    ranked = match_resumes(job_desc, resumes)\n    for r in ranked:\n        r[\"skills\"] = extract_skills(r[\"text\"]) if \"text\" in r else []\n    return {\"ranked\": ranked}\n"},{"label":"React dashboard","fileName":"frontend/src/App.jsx","language":"javascript","content":"import { useState } from \"react\";\n\nexport default function App() {\n  const [jd, setJd] = useState(\"\");\n  const [files, setFiles] = useState([]);\n  const [results, setResults] = useState([]);\n  const [busy, setBusy] = useState(false);\n\n  async function submit() {\n    if (!jd || !files.length) return;\n    setBusy(true);\n    const fd = new FormData();\n    fd.append(\"job_desc\", jd);\n    for (const f of files) fd.append(\"files\", f);\n    try {\n      const r = await fetch(\"http://localhost:8000/screen\", { method: \"POST\", body: fd });\n      const d = await r.json();\n      setResults(d.ranked || []);\n    } finally { setBusy(false); }\n  }\n\n  return (\n    <div style={{ fontFamily: \"sans-serif\", padding: 24, maxWidth: 960, margin: \"0 auto\" }}>\n      <h1>AI Resume Screening</h1>\n      <textarea rows={6} placeholder=\"Paste job description...\" value={jd}\n        onChange={(e) => setJd(e.target.value)} style={{ width: \"100%\", padding: 8 }} />\n      <input type=\"file\" multiple accept=\".pdf\"\n        onChange={(e) => setFiles([...e.target.files])} style={{ margin: \"12px 0\" }} />\n      <button onClick={submit} disabled={busy}>\n        {busy ? \"Screening...\" : \"Screen resumes\"}\n      </button>\n      <ul style={{ marginTop: 16 }}>\n        {results.map((r) => (\n          <li key={r.id} style={{ marginBottom: 8 }}>\n            <strong>{r.name}</strong> — match score: {(r.score * 100).toFixed(1)}%\n            <br/><em>Skills:</em> {r.skills?.join(\", \")}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n"}]$J$,
  'published', 'public', true,
  'admin', NOW(), NOW()
),

-- 3. Enterprise AI Chatbot ──────────────────────────────────────────────────
(
  'proj_ai_chatbot',
  'enterprise-ai-chatbot',
  'Enterprise AI Chatbot',
  'A chatbot that answers employee questions using company documents. Upload PDFs/docs, the system chunks + embeds them, and retrieves the most relevant context for each user question before calling the LLM.',
  'Python / LLM API / FastAPI / React',
  'Advanced',
  'AI',
  '["Document upload + chunking","Vector retrieval (FAISS)","RAG — context-aware LLM responses","Multi-turn chat memory","React chat UI"]',
  $J$[{"label":"README","fileName":"README.md","language":"markdown","content":"# Enterprise AI Chatbot (RAG)\n\nAnswers employee questions using company documents — Retrieval-Augmented Generation.\n\n## Stack\n- Backend: FastAPI + sentence-transformers + FAISS\n- LLM: any OpenAI-compatible chat API (set OPENAI_API_KEY)\n- Frontend: React + Vite\n\n## Run\n```bash\ncd backend && pip install -r requirements.txt\nuvicorn app.main:app --reload --port 8000\ncd ../frontend && npm install && npm run dev\n```\n\n## Endpoints\n- `POST /docs/upload` — upload a PDF/DOCX/TXT\n- `POST /chat` — `{ messages, session_id }` → `{ reply, sources }`\n- `GET /docs` — list uploaded docs\n"},{"label":"Backend deps","fileName":"backend/requirements.txt","language":"text","content":"fastapi==0.115.0\nuvicorn[standard]==0.32.0\nsentence-transformers==3.1.1\nfaiss-cpu==1.8.0.post1\nPyPDF2==3.0.1\nopenai==1.51.0\npython-dotenv==1.0.1\nnumpy==1.26.4\n"},{"label":"Vector store","fileName":"backend/app/retriever.py","language":"python","content":"import faiss, numpy as np\nfrom sentence_transformers import SentenceTransformer\n\n_model = SentenceTransformer(\"all-MiniLM-L6-v2\")\n_dim = 384\n\n# In-memory store — replace with a real DB in production\ndocs = []            # [{ id, text, source, page }]\nindex = faiss.IndexFlatIP(_dim)\n\ndef add(text: str, source: str, page: int = 0):\n    emb = _model.encode([text], normalize_embeddings=True)\n    idx = len(docs)\n    docs.append({\"id\": idx, \"text\": text, \"source\": source, \"page\": page})\n    index.add(np.asarray(emb, dtype=np.float32))\n\ndef search(query: str, k: int = 3) -> list[dict]:\n    if len(docs) == 0:\n        return []\n    q = _model.encode([query], normalize_embeddings=True)\n    D, I = index.search(np.asarray(q, dtype=np.float32), min(k, len(docs)))\n    out = []\n    for score, idx in zip(D[0], I[0]):\n        if idx < 0 or idx >= len(docs): continue\n        d = docs[idx]\n        out.append({\"score\": float(score), \"text\": d[\"text\"], \"source\": d[\"source\"], \"page\": d[\"page\"]})\n    return out\n\ndef chunk(text: str, size: int = 800, overlap: int = 100) -> list[str]:\n    chunks = []\n    i = 0\n    while i < len(text):\n        chunks.append(text[i:i+size])\n        i += size - overlap\n    return chunks\n"},{"label":"RAG chat endpoint","fileName":"backend/app/main.py","language":"python","content":"from fastapi import FastAPI, UploadFile, File\nfrom pydantic import BaseModel\nfrom PyPDF2 import PdfReader\nfrom openai import OpenAI\nfrom app.retriever import add, search, chunk\nimport os, uuid\n\napp = FastAPI(title=\"Enterprise AI Chatbot\", version=\"0.1.0\")\n_client = OpenAI(api_key=os.getenv(\"OPENAI_API_KEY\", \"\"))\n_sessions: dict[str, list[dict]] = {}\n\nclass ChatIn(BaseModel):\n    messages: list[dict]\n    session_id: str | None = None\n\n@app.get(\"/health\")\ndef health(): return {\"status\": \"ok\"}\n\n@app.post(\"/docs/upload\")\nasync def upload(file: UploadFile = File(...)):\n    reader = PdfReader(file.file)\n    for i, page in enumerate(reader.pages):\n        text = page.extract_text() or \"\"\n        for c in chunk(text):\n            add(c, source=file.filename, page=i+1)\n    return {\"filename\": file.filename, \"pages\": len(reader.pages)}\n\n@app.post(\"/chat\")\ndef chat(req: ChatIn):\n    sid = req.session_id or str(uuid.uuid4())\n    history = _sessions.setdefault(sid, [])\n    last_user = next((m[\"content\"] for m in reversed(req.messages) if m[\"role\"] == \"user\"), \"\")\n    sources = search(last_user, k=3)\n    context = \"\\n\\n\".join(s[\"text\"] for s in sources)\n    sys = (\n        \"You are an internal enterprise assistant. Answer ONLY from the context below. \"\n        \"If the answer is not in the context, say you don't know.\\n\\nContext:\\n\" + context\n    )\n    msgs = [{\"role\": \"system\", \"content\": sys}] + req.messages\n    try:\n        r = _client.chat.completions.create(model=\"gpt-4o-mini\", messages=msgs, temperature=0.2)\n        reply = r.choices[0].message.content\n    except Exception as e:\n        reply = f\"(LLM unavailable: {e})\"\n    history.append({\"role\": \"assistant\", \"content\": reply})\n    return {\"reply\": reply, \"sources\": sources, \"session_id\": sid}\n"},{"label":"React chat UI","fileName":"frontend/src/App.jsx","language":"javascript","content":"import { useState } from \"react\";\n\nexport default function App() {\n  const [msgs, setMsgs] = useState([]);\n  const [input, setInput] = useState(\"\");\n  const [sid, setSid] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const [sources, setSources] = useState([]);\n\n  async function send() {\n    if (!input.trim() || busy) return;\n    const next = [...msgs, { role: \"user\", content: input }];\n    setMsgs(next); setInput(\"\"); setBusy(true);\n    try {\n      const r = await fetch(\"http://localhost:8000/chat\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ messages: next, session_id: sid })\n      });\n      const d = await r.json();\n      setMsgs([...next, { role: \"assistant\", content: d.reply }]);\n      setSid(d.session_id); setSources(d.sources || []);\n    } finally { setBusy(false); }\n  }\n\n  return (\n    <div style={{ fontFamily: \"sans-serif\", padding: 24, maxWidth: 720, margin: \"0 auto\" }}>\n      <h2>Enterprise AI Chatbot</h2>\n      <div style={{ minHeight: 300, border: \"1px solid #ddd\", padding: 12, borderRadius: 8 }}>\n        {msgs.map((m, i) => (\n          <div key={i} style={{ textAlign: m.role === \"user\" ? \"right\" : \"left\", margin: \"6px 0\" }}>\n            <span style={{ background: m.role === \"user\" ? \"#0ea5e9\" : \"#e5e7eb\", padding: \"4px 8px\", borderRadius: 6, color: m.role === \"user\" ? \"white\" : \"black\" }}>\n              {m.content}\n            </span>\n          </div>\n        ))}\n      </div>\n      {sources.length > 0 && (\n        <p style={{ fontSize: 12, color: \"#666\" }}>Sources: {sources.map(s => s.source).join(\", \")}</p>\n      )}\n      <div style={{ display: \"flex\", gap: 8, marginTop: 8 }}>\n        <input value={input} onChange={(e) => setInput(e.target.value)}\n          onKeyDown={(e) => e.key === \"Enter\" && send()}\n          style={{ flex: 1, padding: 8 }} placeholder=\"Ask about your docs...\" />\n        <button onClick={send} disabled={busy}>{busy ? \"...\" : \"Send\"}</button>\n      </div>\n    </div>\n  );\n}\n"}]$J$,
  'published', 'public', true,
  'admin', NOW(), NOW()
),

-- 4. Smart Business Dashboard ───────────────────────────────────────────────
(
  'proj_dashboard',
  'smart-business-dashboard',
  'Smart Business Dashboard',
  'KPI dashboards, data filters, reports, and business analytics. Pulls sales/inventory/HR data from Postgres, aggregates by region/period, and renders interactive Chart.js visualisations.',
  'React / Next.js / PostgreSQL / Chart.js',
  'Beginner',
  'Web',
  '["KPI cards (revenue, orders, AOV)","Date + region filters\",\"Drill-down charts with Chart.js\",\"CSV/PDF report export\",\"Server-side aggregation via Prisma\"]',
  $J$[{"label":"README","fileName":"README.md","language":"markdown","content":"# Smart Business Dashboard\n\nKPI dashboards with date + region filters, Chart.js visualisations, and CSV report export.\n\n## Stack\n- Next.js 14 (App Router)\n- Prisma + PostgreSQL\n- Chart.js (react-chartjs-2)\n- TailwindCSS\n\n## Run\n```bash\nnpm install\npsql -f database/schema.sql\nnpm run dev\n```\n\nOpen http://localhost:3000\n"},{"label":"Package deps","fileName":"package.json","language":"json","content":"{\n  \"name\": \"smart-business-dashboard\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\"\n  },\n  \"dependencies\": {\n    \"next\": \"14.2.5\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"@prisma/client\": \"5.18.0\",\n    \"chart.js\": \"4.4.3\",\n    \"react-chartjs-2\": \"5.2.0\",\n    \"date-fns\": \"3.6.0\"\n  },\n  \"devDependencies\": {\n    \"prisma\": \"5.18.0\",\n    \"autoprefixer\": \"10.4.19\",\n    \"postcss\": \"8.4.39\",\n    \"tailwindcss\": \"3.4.7\"\n  }\n}\n"},{"label":"DB schema","fileName":"database/schema.sql","language":"sql","content":"CREATE TABLE IF NOT EXISTS orders (\n  id           SERIAL PRIMARY KEY,\n  order_date   DATE NOT NULL,\n  region        TEXT NOT NULL,\n  product       TEXT NOT NULL,\n  qty           INT NOT NULL,\n  revenue       NUMERIC(12, 2) NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_orders_date   ON orders(order_date);\nCREATE INDEX IF NOT EXISTS idx_orders_region ON orders(region);\n\nINSERT INTO orders (order_date, region, product, qty, revenue)\nSELECT d::date, r, p, (random()*50 + 1)::int, (random()*5000 + 100)::numeric\nFROM generate_series('2024-01-01'::date, '2024-12-31'::date, '1 day'::interval) AS gs(d)\nCROSS JOIN (VALUES ('North'),('South'),('East'),('West')) AS r(r)\nCROSS JOIN (VALUES ('Widget A'),('Widget B'),('Widget C')) AS p(p);\n"},{"label":"Prisma schema","fileName":"prisma/schema.prisma","language":"prisma","content":"generator client {\n  provider = \"prisma-client-js\"\n}\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\nmodel Order {\n  id         Int      @id @default(autoincrement())\n  orderDate  DateTime @db.Date\n  region     String\n  product    String\n  qty        Int\n  revenue    Float\n  @@index([orderDate])\n  @@index([region])\n}\n"},{"label":"API route","fileName":"app/api/kpis/route.ts","language":"typescript","content":"import { NextResponse } from 'next/server';\nimport { PrismaClient } from '@prisma/client';\nimport { sub } from 'date-fns';\n\nconst prisma = new PrismaClient();\n\nexport async function GET(req: Request) {\n  const url = new URL(req.url);\n  const region = url.searchParams.get('region') || 'all';\n  const days  = Number(url.searchParams.get('days') || 30);\n  const since = sub(new Date(), { days });\n\n  const where = {\n    orderDate: { gte: since },\n    ...(region !== 'all' ? { region } : {}),\n  };\n\n  const rows = await prisma.order.findMany({ where, select: { qty: true, revenue: true, orderDate: true } });\n  const totalRevenue = rows.reduce((s, r) => s + r.revenue, 0);\n  const totalOrders  = rows.length;\n  const aov = totalOrders ? totalRevenue / totalOrders : 0;\n\n  // Daily series for chart\n  const byDay = new Map<string, number>();\n  for (const r of rows) {\n    const k = r.orderDate.toISOString().slice(0, 10);\n    byDay.set(k, (byDay.get(k) || 0) + r.revenue);\n  }\n  const labels = [...byDay.keys()].sort();\n  const series = labels.map(l => byDay.get(l)!);\n\n  return NextResponse.json({\n    kpis: {\n      revenue: totalRevenue.toFixed(2),\n      orders: totalOrders,\n      aov: aov.toFixed(2),\n    },\n    chart: { labels, series },\n  });\n}\n"},{"label":"Dashboard page","fileName":"app/page.tsx","language":"tsx","content":"'use client';\nimport { useEffect, useState } from 'react';\nimport { Line } from 'react-chartjs-2';\nimport { Chart, CategoryScale, LinearScale, PointElement, LineElement } from 'chart.js';\nChart.register(CategoryScale, LinearScale, PointElement, LineElement);\n\nexport default function Home() {\n  const [region, setRegion] = useState('all');\n  const [days, setDays] = useState(30);\n  const [data, setData] = useState<any>(null);\n\n  useEffect(() => {\n    fetch(`/api/kpis?region=${region}&days=${days}`).then(r => r.json()).then(setData);\n  }, [region, days]);\n  if (!data) return <p>Loading...</p>;\n  const k = data.kpis;\n  return (\n    <main style={{ padding: 24, fontFamily: 'sans-serif' }}>\n      <h1>Smart Business Dashboard</h1>\n      <div style={{ display: 'flex', gap: 8, margin: '16px 0' }}>\n        <select value={region} onChange={e => setRegion(e.target.value)}>\n          <option value=\"all\">All Regions</option>\n          <option>North</option><option>South</option>\n          <option>East</option><option>West</option>\n        </select>\n        <select value={days} onChange={e => setDays(Number(e.target.value))}>\n          <option value={7}>Last 7 days</option>\n          <option value={30}>Last 30 days</option>\n          <option value={90}>Last 90 days</option>\n        </select>\n      </div>\n      <div style={{ display: 'flex', gap: 16 }}>\n        {[['Revenue', k.revenue], ['Orders', k.orders], ['AOV', k.aov]].map(([l, v]) => (\n          <div key={l} style={{ border: '1px solid #ddd', padding: 16, borderRadius: 8, minWidth: 140 }}>\n            <p style={{ color: '#666', margin: 0 }}>{l}</p>\n            <h2 style={{ margin: '4px 0 0' }}>{v}</h2>\n          </div>\n        ))}\n      </div>\n      <div style={{ marginTop: 24 }}>\n        <Line data={{ labels: data.chart.labels, datasets: [{ label: 'Revenue', data: data.chart.series, borderColor: '#0ea5e9' }] }} />\n      </div>\n    </main>\n  );\n}\n"}]$J$,
  'published', 'public', false,
  'admin', NOW(), NOW()
),

-- 5. Internship Project Management Portal ───────────────────────────────────
(
  'proj_internship_portal',
  'internship-pm-portal',
  'Internship Project Management Portal',
  'Manage student assignments, progress, mentor feedback, and project submissions. Admins assign projects with deadlines; students upload their work; mentors review and provide feedback. Built on Next.js + Prisma + PostgreSQL.',
  'Next.js / Prisma / PostgreSQL',
  'Intermediate',
  'Enterprise',
  '["Admin assigns projects + deadlines\",\"Student upload (GitHub link + report)\",\"Mentor review + feedback\",\"Progress tracking (auto-stage)\",\"Certificate generation\"]',
  $J$[{"label":"README","fileName":"README.md","language":"markdown","content":"# Internship Project Management Portal\n\nA self-hostable clone of this very portal — admin assigns projects, students upload work, mentors review.\n\n## Stack\n- Next.js 16 (App Router)\n- Prisma + PostgreSQL\n- Tailwind + shadcn/ui\n\n## Run\n```bash\nnpm install\nnpm run db:push\nnpm run dev\n```\n\n## Default login\n- Admin: `admin` / `admin123`\n- Student demo: `student@demo.local` / `demo123`\n\n## Project structure\n```\napp/\n  page.tsx\n  api/\n    auth/\n    admin/\n    student/\n  components/\n    ui/\nlib/\n  db.ts\n  auth.ts\nprisma/\n  schema.prisma\n```\n"},{"label":"Package deps","fileName":"package.json","language":"json","content":"{\n  \"name\": \"internship-portal\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"db:push\": \"prisma db push\",\n    \"db:generate\": \"prisma generate\"\n  },\n  \"dependencies\": {\n    \"next\": \"16.0.0\",\n    \"react\": \"19.0.0\",\n    \"react-dom\": \"19.0.0\",\n    \"@prisma/client\": \"6.11.1\",\n    \"bcryptjs\": \"2.4.3\",\n    \"next-auth\": \"4.24.7\",\n    \"zod\": \"3.23.8\"\n  },\n  \"devDependencies\": {\n    \"prisma\": \"6.11.1\",\n    \"typescript\": \"5.5.4\",\n    \"tailwindcss\": \"4.0.0\",\n    \"@types/node\": \"22.5.0\",\n    \"@types/react\": \"19.0.0\"\n  }\n}\n"},{"label":"Prisma schema","fileName":"prisma/schema.prisma","language":"prisma","content":"generator client { provider = \"prisma-client-js\" }\ndatasource db { provider = \"postgresql\"; url = env(\"DATABASE_URL\") }\n\nmodel Account {\n  id           String  @id @default(cuid())\n  username      String  @unique\n  passwordHash  String\n  role          String  @default(\"student\")\n  createdAt     DateTime @default(now())\n}\n\nmodel Project {\n  id          String  @id @default(cuid())\n  title       String\n  description String\n  deadline    DateTime?\n  createdAt   DateTime @default(now())\n  assignments Assignment[]\n}\n\nmodel Assignment {\n  id           String   @id @default(cuid())\n  projectId     String\n  project       Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  studentEmail  String\n  status        String   @default(\"assigned\")\n  feedback      String?\n  assignedAt    DateTime @default(now())\n  submittedAt   DateTime?\n  reviewedAt    DateTime?\n  @@unique([projectId, studentEmail])\n}\n"},{"label":"Auth helper","fileName":"lib/auth.ts","language":"typescript","content":"import { SignJWT, jwtVerify } from 'jose';\nimport bcrypt from 'bcryptjs';\nimport { db } from './db';\n\nconst SECRET = new TextEncoder().encode(process.env.SESSION_SECRET || 'dev-secret');\n\nexport async function login(username: string, password: string) {\n  const acct = await db.account.findUnique({ where: { username } });\n  if (!acct) return null;\n  if (!await bcrypt.compare(password, acct.passwordHash)) return null;\n  const token = await new SignJWT({ username: acct.username, role: acct.role })\n    .setProtectedHeader({ alg: 'HS256' })\n    .setExpirationTime('7d')\n    .sign(SECRET);\n  return token;\n}\n\nexport async function verify(token: string) {\n  try {\n    const { payload } = await jwtVerify(token, SECRET);\n    return payload as { username: string; role: string };\n  } catch { return null; }\n}\n"},{"label":"Admin assign API","fileName":"app/api/admin/assign/route.ts","language":"typescript","content":"import { NextResponse } from 'next/server';\nimport { db } from '@/lib/db';\nimport { verify } from '@/lib/auth';\n\nexport async function POST(req: Request) {\n  const auth = req.headers.get('cookie') || '';\n  const token = auth.split(';').map(c => c.trim()).find(c => c.startsWith('token='))?.split('=')[1];\n  const session = token ? await verify(token) : null;\n  if (!session || session.role !== 'admin')\n    return NextResponse.json({ error: 'forbidden' }, { status: 403 });\n\n  const { projectId, studentEmail, deadline } = await req.json();\n  const a = await db.assignment.upsert({\n    where: { projectId_studentEmail: { projectId, studentEmail } },\n    create: { projectId, studentEmail, status: 'assigned', deadline: deadline ? new Date(deadline) : null },\n    update: { deadline: deadline ? new Date(deadline) : null }\n  });\n  return NextResponse.json({ ok: true, assignment: a });\n}\n"},{"label":"Student submit API","fileName":"app/api/student/submit/route.ts","language":"typescript","content":"import { NextResponse } from 'next/server';\nimport { db } from '@/lib/db';\nimport { verify } from '@/lib/auth';\n\nexport async function POST(req: Request) {\n  const auth = req.headers.get('cookie') || '';\n  const token = auth.split(';').map(c => c.trim()).find(c => c.startsWith('token='))?.split('=')[1];\n  const session = token ? await verify(token) : null;\n  if (!session)\n    return NextResponse.json({ error: 'unauthenticated' }, { status: 401 });\n\n  const { assignmentId, githubLink, report } = await req.json();\n  const a = await db.assignment.update({\n    where: { id: assignmentId },\n    data: { status: 'submitted', submittedAt: new Date(), githubLink, report }\n  });\n  return NextResponse.json({ ok: true, assignment: a });\n}\n"}]$J$,
  'published', 'public', false,
  'admin', NOW(), NOW()
);

SELECT slug, title, techStack, difficulty, status, featured
FROM "ProjectLibraryItem"
WHERE slug IN (
  'ai-procurement-assistant',
  'ai-resume-screening',
  'enterprise-ai-chatbot',
  'smart-business-dashboard',
  'internship-pm-portal'
)
ORDER BY featured DESC, title;
